    "css": ".blk-chart-bar{\n    --cb-line: color-mix(in srgb, var(--brand-ink,#f4f2ff) 12%, transparent);\n    --cb-soft: color-mix(in srgb, var(--brand-ink,#f4f2ff) 6%, transparent);\n    --cb-grid: color-mix(in srgb, var(--brand-ink,#f4f2ff) 10%, transparent);\n    --cb-mut:  color-mix(in srgb, var(--brand-ink,#f4f2ff) 55%, transparent);\n    font-family: var(--brand-font-body, system-ui, sans-serif);\n    color: var(--brand-ink,#f4f2ff);\n    background: var(--cb-soft);\n    border: 1px solid var(--cb-line);\n    border-radius: 14px;\n    padding: 20px 22px;\n  }\n  .blk-chart-bar .cb-title{\n    font-size: 12px; text-transform: uppercase; letter-spacing: .14em; color: var(--cb-mut); margin: 0 0 16px;\n  }\n  .blk-chart-bar .cb-svg{ width: 100%; height: auto; display: block; }\n  .blk-chart-bar .cb-grid line{ stroke: var(--cb-grid); stroke-width: 1; }\n  .blk-chart-bar .cb-label{ font-size: 8.5px; fill: var(--cb-mut); }\n  .blk-chart-bar .cb-bar{ transition: opacity .15s ease-out; }\n  .blk-chart-bar .cb-bar:hover, .blk-chart-bar .cb-bar:focus-visible{ opacity: .78; outline: none; }\n  .blk-chart-bar .cb-empty{ display: none; align-items: center; gap: 10px; color: var(--cb-mut); font-size: 13.5px; min-height: 140px; }\n  .blk-chart-bar[data-empty] .cb-wrap{ display: none; }\n  .blk-chart-bar[data-empty] .cb-empty{ display: flex; }\n  @media (prefers-reduced-motion: reduce){ .blk-chart-bar .cb-bar{ transition: none; } }",
    "javascript": "(function () {\n  document.querySelectorAll('.blk-chart-bar').forEach(function (root) {\n    if (root.dataset.wired) return; root.dataset.wired = '1';\n    var pts = [];\n    try { pts = JSON.parse((root.querySelector('script[data-fill=\"series\"]') || {}).textContent || '[]'); } catch (e) { pts = []; }\n    if (!Array.isArray(pts)) pts = [];\n    pts = pts.filter(function (p) { return p && Array.isArray(p.values) && p.values.length > 0; });\n    if (!pts.length) { root.setAttribute('data-empty', ''); return; }\n    root.removeAttribute('data-empty');\n\n    var W = 300, H = 160, padB = 18, padT = 6, chartH = H - padB - padT;\n    var maxV = Math.max.apply(null, pts.map(function (p) { return Math.max.apply(null, p.values); }));\n    maxV = maxV || 1;\n    var colors = ['var(--brand-accent,#8b7bff)', 'var(--brand-mid,#2a2450)'];\n    var svg = root.querySelector('.cb-svg');\n    var gridG = root.querySelector('.cb-grid');\n    var barsG = root.querySelector('.cb-bars');\n    var labelsG = root.querySelector('.cb-labels');\n\n    for (var g = 0; g < 4; g++) {\n      var y = padT + (chartH / 3) * g;\n      var line = document.createElementNS('http://www.w3.org/2000/svg', 'line');\n      line.setAttribute('x1', 0); line.setAttribute('x2', W); line.setAttribute('y1', y); line.setAttribute('y2', y);\n      gridG.appendChild(line);\n    }\n\n    var n = pts.length;\n    var slot = W / n;\n    var seriesCount = Math.min(3, pts[0].values.length);\n    var barW = Math.min(20, (slot * 0.6) / seriesCount);\n\n    pts.forEach(function (p, i) {\n      var cx = slot * i + slot / 2;\n      var groupW = barW * seriesCount + (seriesCount - 1) * 2;\n      var startX = cx - groupW / 2;\n      p.values.slice(0, 3).forEach(function (v, si) {\n        var h = (v / maxV) * chartH;\n        var rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');\n        rect.setAttribute('class', 'cb-bar');\n        rect.setAttribute('x', startX + si * (barW + 2));\n        rect.setAttribute('y', padT + chartH - h);\n        rect.setAttribute('width', barW);\n        rect.setAttribute('height', Math.max(h, 1));\n        rect.setAttribute('rx', 3);\n        rect.setAttribute('fill', colors[si] || colors[colors.length - 1]);\n        rect.setAttribute('tabindex', '0');\n        var t = document.createElementNS('http://www.w3.org/2000/svg', 'title');\n        t.textContent = p.label + ': ' + v;\n        rect.appendChild(t);\n        barsG.appendChild(rect);\n      });\n      var label = document.createElementNS('http://www.w3.org/2000/svg', 'text');\n      label.setAttribute('class', 'cb-label');\n      label.setAttribute('x', cx); label.setAttribute('y', H - 4); label.setAttribute('text-anchor', 'middle');\n      label.textContent = p.label;\n      labelsG.appendChild(label);\n    });\n\n    svg.setAttribute('aria-label', 'Bar chart: ' + pts.map(function (p) { return p.label + ' ' + p.values.join('/'); }).join(', '));\n  });\n})();"
