    "css": ".blk-chart-donut{\n    --cd-line: color-mix(in srgb, var(--brand-ink,#f4f2ff) 12%, transparent);\n    --cd-soft: color-mix(in srgb, var(--brand-ink,#f4f2ff) 6%, transparent);\n    --cd-mut:  color-mix(in srgb, var(--brand-ink,#f4f2ff) 55%, transparent);\n    --cd-s3:   color-mix(in srgb, var(--brand-ink,#f4f2ff) 45%, transparent);\n    font-family: var(--brand-font-body, system-ui, sans-serif);\n    color: var(--brand-ink,#f4f2ff);\n    background: var(--cd-soft);\n    border: 1px solid var(--cd-line);\n    border-radius: 14px;\n    padding: 20px 22px;\n  }\n  .blk-chart-donut .cd-title{\n    font-size: 12px; text-transform: uppercase; letter-spacing: .14em;\n    color: var(--cd-mut); margin: 0 0 16px;\n  }\n  .blk-chart-donut .cd-wrap{ display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }\n  .blk-chart-donut .cd-svg{ width: 132px; height: 132px; flex-shrink: 0; }\n  .blk-chart-donut .cd-track{ stroke: var(--cd-line); }\n  .blk-chart-donut .cd-seg{ transition: stroke-width .18s ease-out; }\n  .blk-chart-donut .cd-seg:hover, .blk-chart-donut .cd-seg:focus-visible{ stroke-width: 13; outline: none; }\n  .blk-chart-donut .cd-total{\n    font-family: var(--brand-font-head, Georgia, serif);\n    font-size: 24px; font-weight: 600; fill: var(--brand-ink,#f4f2ff);\n    font-variant-numeric: tabular-nums;\n  }\n  .blk-chart-donut .cd-total-label{ font-size: 9px; letter-spacing: .12em; text-transform: uppercase; fill: var(--cd-mut); }\n  .blk-chart-donut .cd-legend{ list-style: none; margin: 0; padding: 0; display: grid; gap: 9px; min-width: 150px; flex: 1; }\n  .blk-chart-donut .cd-legend li{ display: flex; align-items: center; gap: 9px; font-size: 13.5px; }\n  .blk-chart-donut .cd-dot{ width: 9px; height: 9px; border-radius: 999px; flex-shrink: 0; }\n  .blk-chart-donut .cd-legend .cd-val{ margin-left: auto; color: var(--cd-mut); font-variant-numeric: tabular-nums; }\n  .blk-chart-donut .cd-empty{ display: none; align-items: center; gap: 10px; color: var(--cd-mut); font-size: 13.5px; min-height: 132px; }\n  .blk-chart-donut[data-empty] .cd-wrap{ display: none; }\n  .blk-chart-donut[data-empty] .cd-empty{ display: flex; }\n  @media (prefers-reduced-motion: reduce){ .blk-chart-donut .cd-seg{ transition: none; } }",
    "javascript": "(function () {\n  var CIRC = 2 * Math.PI * 40; // r=40 in the 100-viewBox\n  document.querySelectorAll('.blk-chart-donut').forEach(function (root) {\n    if (root.dataset.wired) return; root.dataset.wired = '1';\n    var segs = [];\n    try { segs = JSON.parse((root.querySelector('script[data-fill=\"segments\"]') || {}).textContent || '[]'); } catch (e) { segs = []; }\n    if (!Array.isArray(segs)) segs = [];\n    segs = segs.filter(function (s) { return s && typeof s.value === 'number' && s.value > 0; });\n    if (!segs.length) { root.setAttribute('data-empty', ''); return; }\n    root.removeAttribute('data-empty');\n\n    var total = segs.reduce(function (n, s) { return n + s.value; }, 0);\n    var colors = [\n      'var(--brand-accent,#8b7bff)',\n      'var(--brand-mid,#2a2450)',\n      'var(--cd-s3)'\n    ];\n    var g = root.querySelector('.cd-segs');\n    var legend = root.querySelector('.cd-legend');\n    var svg = root.querySelector('.cd-svg');\n    var offset = 0;\n    segs.slice(0, 3).forEach(function (s, i) {\n      var frac = s.value / total;\n      var c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');\n      c.setAttribute('class', 'cd-seg');\n      c.setAttribute('cx', '50'); c.setAttribute('cy', '50'); c.setAttribute('r', '40');\n      c.setAttribute('fill', 'none');\n      c.setAttribute('stroke', colors[i]);\n      c.setAttribute('stroke-width', '11');\n      c.setAttribute('stroke-dasharray', (frac * CIRC) + ' ' + CIRC);\n      c.setAttribute('stroke-dashoffset', String(-offset * CIRC));\n      c.setAttribute('tabindex', '0');\n      var t = document.createElementNS('http://www.w3.org/2000/svg', 'title');\n      t.textContent = s.label + ': ' + s.value + ' (' + Math.round(frac * 100) + '%)';\n      c.appendChild(t);\n      g.appendChild(c);\n      offset += frac;\n\n      var li = document.createElement('li');\n      var dot = document.createElement('span'); dot.className = 'cd-dot'; dot.style.background = colors[i];\n      var name = document.createElement('span'); name.textContent = s.label;\n      var val = document.createElement('span'); val.className = 'cd-val'; val.textContent = Math.round(frac * 100) + '%';\n      li.appendChild(dot); li.appendChild(name); li.appendChild(val);\n      legend.appendChild(li);\n    });\n    root.querySelector('.cd-total').textContent = String(total);\n    svg.setAttribute('aria-label', 'Donut chart: ' + segs.map(function (s) { return s.label + ' ' + s.value; }).join(', '));\n  });\n})();"
